'use client';

/**
 * <RoxyWesternPlanetsTable data={...} />: Western planetary positions table with sign, degree, house, and motion plus the chart angles.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/western-planets-table/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.astrology.generateNatalChart({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyWesternPlanetsTable as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyWesternPlanetsTableProps = ComponentProps<typeof Element>;

export function RoxyWesternPlanetsTable(props: RoxyWesternPlanetsTableProps) {
	return <Element {...props} />;
}

export default RoxyWesternPlanetsTable;
